it('notifies onError for a rejection without string conversion (spec: specs/hal-engine-config-hooks/spec.md#8)', async () => {
  const failure: unknown = Object.create(null);
  let received: Error | undefined;
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Assistant'}), undefined, {
    hooks: {
      beforeSession: async () => {
        throw failure;
      },
      onError: async (_session, error) => {
        received = error;
      },
    },
  });

  await expect(orchestrator.processMessage(session)).rejects.toBe(failure);
  expect(received).toBeInstanceOf(Error);
  expect(received?.cause).toBe(failure);
  expect(received?.message).toBeTruthy();
});
EOF
